    class ConvoiMax {
        static init() {
            "use strict";
            if (Commun.comptePlus) return;
            function lireNombre(id) {
                return Commun.nombre(document.getElementById(id)?.textContent);
            }
            const formulaire = document.querySelector('form[action="commerce.php"]');
            const boutonEnvoi = formulaire?.querySelector('input[name="convoi"]');
            const explication = document.getElementById("explication_convois");
            if (!formulaire || !boutonEnvoi || !explication) {
                return;
            }
            const niveau = explication.textContent.match(/(?:étable niveau|level)\s+(\d+)/i);
            if (!niveau) {
                console.warn("ConvoiMax : niveau d'étable introuvable.");
                return;
            }
            const etable = Number(niveau[1]);
            const capaciteParOuvriere = 10 + etable / 2;
            const champs = {
                nourriture: document.getElementById("input_nbNourriture"),
                materiaux: document.getElementById("input_nbMateriaux"),
                ouvrieres: document.getElementById("input_nbOuvriere"),
                valeurNourriture: document.getElementById("nbNourriture"),
                valeurMateriaux: document.getElementById("nbMateriaux"),
                valeurOuvrieres: document.getElementById("nbOuvriere")
            };
            if (Object.values(champs).some(champ => !champ)) {
                return;
            }
            function definir(champ, valeur) {
                champ.value = valeur;
                champ.dispatchEvent(new Event("input", { bubbles: true }));
                champ.dispatchEvent(new Event("change", { bubbles: true }));
            }
            function vider() {
                Object.values(champs).forEach(function (champ) {
                    definir(champ, "");
                });
            }
            function remplir(type) {
                vider();
                const ouvrieres = lireNombre("nb_ouvrieres");
                const tdc = lireNombre("quantite_tdc");
                const disponibles = Math.max(0, ouvrieres - tdc);
                const stock = lireNombre(type === "nourriture" ? "nb_nourriture" : "nb_materiaux");
                const maximum = Math.floor(Math.min(Math.floor(disponibles * capaciteParOuvriere), stock));
                const necessaires = Math.ceil(maximum / capaciteParOuvriere);
                const champCache = type === "nourriture" ? champs.valeurNourriture : champs.valeurMateriaux;
                definir(champs[type], String(maximum));
                definir(champCache, String(maximum));
                definir(champs.ouvrieres, String(necessaires));
                definir(champs.valeurOuvrieres, String(necessaires));
            }
            const conteneur = document.createElement("div");
            conteneur.style.cssText = "display:flex;justify-content:center;gap:10px;margin:0 0 12px";
            function creerBouton(texte, type) {
                const bouton = document.createElement("button");
                bouton.type = "button";
                bouton.textContent = texte;
                bouton.style.cssText = "cursor:pointer;padding:6px 12px;border-radius:6px";
                bouton.addEventListener("click", function () {
                    remplir(type);
                });
                return bouton;
            }
            conteneur.appendChild(creerBouton("Max pommes", "nourriture"));
            conteneur.appendChild(creerBouton("Max matériaux", "materiaux"));
            boutonEnvoi.parentNode.insertBefore(conteneur, boutonEnvoi);
        }
    }
    class BilanNiveaux {
        static regrouper(rapports, filtre = () => true) {
            const groupes = new Map();
            for (const r of rapports) {
                if (!filtre(r)) continue;
                const pseudo = r.defense ? r.attaquant : r.cible;
                if (!pseudo || ['vous', 'adversaire'].includes(Commun.norm(pseudo))) continue;
                const cle = Commun.norm(pseudo);
                if (!groupes.has(cle)) groupes.set(cle, {pseudo, rapports: []});
                groupes.get(cle).rapports.push(r);
            }
            return groupes;
        }
        static trier(rapports) { return rapports.filter(r => Number.isFinite(r.date?.ms)).sort((a, b) => a.date.ms - b.date.ms); }
        static consolider(ensembles) {
            const votes = new Map(), total = ensembles.length;
            for (const ensemble of ensembles) {
                for (const niveau of ensemble) votes.set(niveau, (votes.get(niveau) || 0) + 1);
            }
            const maximum = Math.max(0, ...votes.values());
            const niveaux = [...votes].filter(([, n]) => n === maximum).map(([niveau]) => niveau).sort((a, b) => a - b);
            const commun = total > 0 && maximum === total;
            const probable = !commun && maximum > total / 2;
            return {niveaux, maximum, total, commun, probable};
        }
        static synthese(type, bilan) {
            const {niveaux, maximum, total, commun, probable} = bilan;
            if (!total) return `${type} non déterminable`;
            if (commun) return `${type} : ${niveaux.join(', ')} (${maximum}/${total} concordants)`;
            if (probable) return `${type} probable : ${niveaux.join(', ')} (${maximum}/${total} concordants)`;
            return `${type} : estimations contradictoires`;
        }
        static titre(type, calculs, exploitables, sections, bilans) {
            if (!sections.length) return '';
            const resume = `${calculs} calcul${calculs > 1 ? 's' : ''}, ${exploitables} exploitable${exploitables > 1 ? 's' : ''}`;
            const b = bilans.length === 1 ? bilans[0] : null;
            const niveaux = b?.commun ? `, ${b.niveaux.join(', ')} possible${b.niveaux.length > 1 ? 's' : ''}` : b?.probable ? `, ${b.niveaux.join(', ')} probable${b.niveaux.length > 1 ? 's' : ''}` : '';
            return `<section id="rc-bilan-${type.toLowerCase()}"><h3>Bilan ${type} — ${resume}${niveaux}</h3>${sections.join('')}</section>`;
        }
    }
    class CalculVA {
        static TOLERANCE = 60; static VA_MAX = 50;
        static candidats(distance, duree) {
            if (!Number.isFinite(distance) || distance <= 0 || duree <= 0) return [];
            const candidats = [];
            for (let va = 0; va <= this.VA_MAX; va++) {
                const temps = TempsTrajet.tempsDepuisDistance(va, distance);
                const ecart = Math.abs(temps - duree);
                if (ecart <= this.TOLERANCE) candidats.push({va, temps, ecart});
            }
            return candidats.sort((a, b) => a.ecart - b.ecart);
        } 
        static minimum(distance, duree) { if (!Number.isFinite(distance) || distance <= 0 || duree <= 0) return null; for (let va = 0; va <= this.VA_MAX; va++) { if (TempsTrajet.tempsDepuisDistance(va, distance) <= duree + this.TOLERANCE) return va; } return null; }    
        static async bilan(rapports) {
            const groupes = BilanNiveaux.regrouper(rapports, r => r.defense);
            const sections = [], bilans = [];
            const esc = Commun.echapper;
            let calculs = 0, exploitables = 0;
            for (const {pseudo, rapports: groupe} of groupes.values()) {
                if (groupe.length < 2) continue;
                const dates = BilanNiveaux.trier(groupe);
                const lignes = [], ensembles = [];
                for (let i = 1; i < dates.length; i++) {
                    const precedent = dates[i - 1], courant = dates[i];
                    const duree = (courant.date.ms - precedent.date.ms) / 1000;
                    let distance = null, candidats = [], observation = '';
                    if (duree <= 0) observation = 'Chronologie insuffisante';
                    else if (!courant.cible || ['vous', 'adversaire'].includes(Commun.norm(courant.cible))) observation = 'Auteur à identifier';
                    else {
                        try {
                            distance = await DonneesJoueur.distance(pseudo, courant.cible);
                            if (!Number.isFinite(distance) || distance <= 0) throw new Error('Distance invalide');
                            calculs++;
                            candidats = this.candidats(distance, duree);
                            if (candidats.length) {
                                exploitables++;
                                ensembles.push(new Set(candidats.map(c => c.va)));
                            } else {
                                const minimum = this.minimum(distance, duree);
                                observation = minimum !== null ? `VA minimale : ${minimum}` : 'Aucune VA compatible';
                            }                        
                        } catch (e) {
                            observation = 'Coordonnées indisponibles';
                        }
                    }
                    lignes.push(`<tr><td>${esc(precedent.date.texte)} → ${esc(courant.date.texte)}</td><td>${esc(courant.cible)}</td><td>${distance === null ? '—' : distance.toFixed(2)}</td><td>${Commun.fmt(duree)} s</td><td${candidats.length ? ' class="rc-niveau-compatible"' : ''}>${candidats.map(c => c.va).join(', ') || '—'}</td><td>${esc(observation)}</td></tr>`);
                }
                const bilan = BilanNiveaux.consolider(ensembles);
                bilans.push(bilan);
                const synthese = BilanNiveaux.synthese('VA', bilan);
                sections.push(`<details class="rc-combat fz-detail"><summary><strong>${esc(pseudo)}</strong> — ${esc(synthese)} — ${groupe.length} RC</summary><div class="rc-interieur"><p>${ensembles.length}/${Math.max(0, dates.length - 1)} intervalles compatibles</p><table><thead><tr><th>Rapports</th><th>Cible</th><th>Distance</th><th>Durée</th><th>VA compatibles</th><th>Observation</th></tr></thead><tbody>${lignes.join('')}</tbody></table></div></details>`);
            }
            return BilanNiveaux.titre('VA', calculs, exploitables, sections, bilans);
        }        
    }
    class CalculTDP {
        static FAMILLES = Object.freeze([[0, 1, 2], [3, 4, 9], [5, 6], [7, 8], [10, 11], [12, 13]].map((noeuds) => ({noeuds})));
        static TOLERANCE_UNITES = 1.5;
        static PONDABLE(i) { return i !== 6 && i !== 11; }
        static resoudreFamille(noeuds, s, c) {
            const m = noeuds.length, nv = m - 1;
            const d = noeuds.map((n) => c[n] - s[n]);
            const p = noeuds.map((_, j) => { const coef = Array(nv).fill(0); if (j > 0) coef[j - 1] -= 1; if (j < nv) coef[j] += 1; return {coef, cst: d[j]}; });
            const contraintes = [];
            for (let j = 0; j < nv; j++) { const coef = Array(nv).fill(0); coef[j] = 1; contraintes.push({coef, cst: 0}); }
            noeuds.forEach((n, j) => { contraintes.push(p[j]); if (!this.PONDABLE(n)) contraintes.push({coef: p[j].coef.map((v) => -v), cst: -p[j].cst}); });
            const ok = (x) => contraintes.every((k) => k.coef.reduce((t, v, i) => t + v * x[i], k.cst) >= -1e-9);
            const sommets = [];
            const ajouter = (x) => { if (x.every(Number.isFinite) && ok(x) && !sommets.some((y) => y.every((v, i) => Math.abs(v - x[i]) < 1e-9))) sommets.push(x); };
            if (nv === 1) { for (const k of contraintes) if (k.coef[0]) ajouter([-k.cst / k.coef[0]]); } else if (nv === 2) { for (let i = 0; i < contraintes.length; i++) { for (let k = i + 1; k < contraintes.length; k++) { const A = contraintes[i], B = contraintes[k]; const det = A.coef[0] * B.coef[1] - A.coef[1] * B.coef[0]; if (Math.abs(det) < 1e-12) continue; ajouter([(-A.cst * B.coef[1] + B.cst * A.coef[1]) / det, (-B.cst * A.coef[0] + A.cst * B.coef[0]) / det]); } } }
            if (!sommets.length) return {faisable: false, d};
            const evalP = (x) => p.map((l) => Math.round(l.coef.reduce((t, v, i) => t + v * x[i], l.cst)));
            const solutions = sommets.map((x) => { const pj = evalP(x); return {x: x.map(Math.round), p: pj, S: pj.reduce((t, v, j) => t + v * Commun.UNITES.TEMPS[noeuds[j]], 0)}; }); const parMin = solutions.reduce((a, b) => (b.S < a.S ? b : a));
            const parMax = solutions.reduce((a, b) => (b.S > a.S ? b : a));
            return { faisable: true, noeuds, d, solutions, parMin, parMax, pMin: noeuds.map((_, j) => Math.min(...solutions.map((v) => v.p[j]))), pMax: noeuds.map((_, j) => Math.max(...solutions.map((v) => v.p[j]))) };
        }
        static candidatsTDP(Smin, Smax, tm, dt) { const candidats = []; let minimum = null; if (Smax <= 0) return {candidats, minimum}; for (let tdp = 0; tdp <= 150; tdp++) { const f = Math.pow(0.9, tdp), tol = this.TOLERANCE_UNITES * tm * f; if (Smin * f - tol <= dt && minimum === null) minimum = tdp; if (Smin * f - tol <= dt && dt <= Smax * f + tol) candidats.push({tdp, f, tmin: Smin * f, tmax: Smax * f, tol}); } return {candidats, minimum}; }
        static comparer(r1, r2, dt) { const familles = this.FAMILLES.map((f) => ({...f, ...this.resoudreFamille(f.noeuds, r1.survivants, r2.avant)})); const faisable = familles.every((f) => f.faisable); let Smin = 0, Smax = 0, tm = 0; if (faisable) { for (const f of familles) { Smin += f.parMin.S; Smax += f.parMax.S; f.noeuds.forEach((n, j) => { if (f.pMax[j] > 0) tm = Math.max(tm, Commun.UNITES.TEMPS[n]); }); } } const calcul = faisable ? this.candidatsTDP(Smin, Smax, tm, dt) : {candidats: [], minimum: null}; return {familles, faisable, Smin, Smax, tm, dt, ...calcul}; }
        static bilan(rapports) {
            const groupes = BilanNiveaux.regrouper(rapports);
            const sections = [], bilans = [];
            const esc = Commun.echapper;
            let calculs = 0, exploitables = 0;
            for (const {pseudo, rapports: groupe} of groupes.values()) {
                if (groupe.length < 2) continue;
                const dates = BilanNiveaux.trier(groupe);
                const lignes = [], ensembles = [];
                for (let i = 1; i < dates.length; i++) {
                    const premier = dates[i - 1], second = dates[i];
                    const dt = (second.date.ms - premier.date.ms) / 1000;
                    if (dt <= 0) {
                        lignes.push(`<tr><td>${esc(premier.date.texte)} → ${esc(second.date.texte)}</td><td>0 min</td><td colspan="3">Même minute : chronologie insuffisante</td></tr>`);
                        continue;
                    }
                    const apres = premier.defense ? premier.finAtt : premier.finDef;
                    const nouveau = second.defense ? second.a : second.d;
                    calculs++;
                    const comparaison = this.comparer({survivants: apres}, {avant: nouveau}, dt);
                    const compatibles = comparaison.candidats.map(c => c.tdp);
                    const pondus = comparaison.faisable ? Commun.somme(comparaison.familles.flatMap(f => f.d)) : null;
                    const avertissement = dt >= 1800 ? 'Très peu fiable' : dt >= 900 ? 'Peu fiable' : 'Fiable';
                    let resultat;
                    if (!comparaison.faisable) resultat = 'Effectifs incompatibles avec ponte + XP seules';
                    else if (comparaison.Smax <= 0) resultat = 'Aucune ponte identifiable';
                    else if (compatibles.length) {
                        resultat = compatibles.join(', ');
                        exploitables++;
                        ensembles.push(new Set(compatibles));
                    } else resultat = comparaison.minimum === null ? 'Aucun TDP compatible' : `Aucun TDP exact (borne indicative ≥ ${comparaison.minimum})`;
                    const duree = dt < 3600 ? `${Math.round(dt / 60)} min` : `${(dt / 3600).toLocaleString('fr-FR', {maximumFractionDigits: 2})} h`;
                    lignes.push(`<tr><td>${esc(premier.date.texte)} → ${esc(second.date.texte)}</td><td>${duree}</td><td>${pondus === null ? '—' : Commun.fmt(pondus)}</td><td${compatibles.length ? ' class="rc-niveau-compatible"' : ''}>${esc(resultat)}</td><td>${esc(avertissement)}</td></tr>`);
                }
                const bilan = BilanNiveaux.consolider(ensembles);
                bilans.push(bilan);
                const synthese = BilanNiveaux.synthese('TDP', bilan);
                sections.push(`<details class="rc-combat rc-tdp"><summary><strong>${esc(pseudo)}</strong> — ${esc(synthese)} — ${groupe.length} RC</summary><div class="rc-interieur"><p>${ensembles.length}/${Math.max(0, dates.length - 1)} intervalles compatibles</p>${lignes.length ? `<table><thead><tr><th>Rapports</th><th>Durée</th><th>Pondues</th><th>TDP compatibles</th><th>Observation</th></tr></thead><tbody>${lignes.join('')}</tbody></table>` : '<p>Dates insuffisantes.</p>'}<p class="rc-note">Hypothèse : les variations proviennent de la ponte et de l’XP. Déplacements, combats intermédiaires ou ponte non continue peuvent fausser le résultat.</p></div></details>`);
            }
            return BilanNiveaux.titre('TDP', calculs, exploitables, sections, bilans);
        }        
    }
    class MembrePage {
        static trouverTableauScore(boite) {
            if (!boite) return null;
            return boite.querySelector(
                '.tableau_score, .tableauscore'
            );
        }
        static trouverBoitesMembre(centre) {
            return Array.from(
                centre.querySelectorAll('.boite_membre')
            );
        }
        static inverserAffichage() {
            const centre = document.querySelector('#centre');
            if (!centre) return false;
            const boites = this.trouverBoitesMembre(centre);
            if (boites.length < 2) return false;
            const boiteTableau = boites.find(
                boite => this.trouverTableauScore(boite)
            );
            if (!boiteTableau) return false;
            const tableauScore = this.trouverTableauScore(boiteTableau);
            const boiteCible = boites.find(
                boite => boite !== boiteTableau
            );
            if (!boiteCible) return false;
            const parentCommun = boiteTableau.parentElement;
            if (!parentCommun) return false;
            boiteCible.appendChild(tableauScore);
            boiteCible.style.display = 'flex';
            boiteCible.style.flexWrap = 'wrap';
            boiteCible.style.gap = '20px';
            boiteCible.style.alignItems = 'center';
            boiteCible.style.justifyContent = 'center';
            parentCommun.insertBefore(
                boiteCible,
                boiteTableau
            );
            return true;
        }
        static init() {
            if (location.pathname.toLowerCase() !== '/membre.php') return;
            this.inverserAffichage();
        }
    }
    class TempsTrajet {
        static distance(a, b) { return Math.hypot(a.x - b.x, a.y - b.y); }
        static tempsDepuisDistance(niveau, distance) { return Math.ceil(Math.pow(0.9, niveau) * 637200 * (1 - Math.exp(-distance / 350))); }
        static formatDuree(s) { const j = Math.floor(s / 86400), h = Math.floor((s % 86400) / 3600), m = Math.floor((s % 3600) / 60), sec = s % 60; return (j ? j + 'j ' : '') + (h || j ? h + 'h ' : '') + (m || h || j ? m + 'm ' : '') + sec + 's'; }
        static async mesInfos() { const [coords, niveaux] = await Promise.all([ DonneesJoueur.coordonnees(), DonneesJoueur.laboratoire() ]); const niveau = niveaux[6]; if (!coords || !Number.isFinite(niveau)) throw new Error('infos introuvables'); return {x: coords.x, y: coords.y, niveau}; }
        static ajouterLigne(texte) { const lien = document.querySelector( '.boite_membre a[href^="commerce.php?ID="]' ); if (!lien) return false; const cellule = lien.closest('td'); if (!cellule) return false; let ligne = document.getElementById('tt_ligne'); if (!ligne) { ligne = document.createElement('div'); ligne.id = 'tt_ligne'; ligne.style.marginTop = '8px'; cellule.appendChild(ligne); } ligne.textContent = 'Temps de trajet : '; const valeur = document.createElement('strong'); valeur.textContent = texte; ligne.appendChild(valeur); return true; }        
        static async init() { if (!/\/Membre\.php/i.test(location.pathname)) return; if (document.getElementById('tt_ligne')) return; const ligneNative = Array.from( document.querySelectorAll('.boite_membre tr') ).find(tr => tr.cells.length >= 2 && /^Temps de trajet\s*:/i.test( tr.cells[0].textContent.trim() ) ); if (ligneNative) { const texte = ligneNative.cells[1].textContent.trim(); if (texte && this.ajouterLigne(texte)) { ligneNative.remove(); return; } } const cible = DonneesJoueur.position(document); if (!cible) return; try { const moi = await this.mesInfos(); if (moi.x === cible.x && moi.y === cible.y) return; const duree = this.tempsDepuisDistance(moi.niveau, this.distance(moi, cible)); this.ajouterLigne(this.formatDuree(duree)); } catch (e) { this.ajouterLigne( 'indisponible (ouvrez votre laboratoire)' ); } }        
    }
    Commun.initialiser();
    DonneesJoueur.reprendrePageOuverte();
    MembrePage.init();
    Analyses.init();
    Rc.init();
    BilanTdC.init();
    Chasseurs.init();
    ConvoiMax.init();
    TempsTrajet.init();
